 async function grade(){const t=test();if(!t||t.status==='draft'||gradeBusy)return;gradeBusy=true;render({keepScroll:true});try{for(const id of t.ids){if(t.entries[id].assessment)continue;const card=byId.get(id);if(Q.isVisual(card))continue;if(!t.entries[id].answer.trim()){apply(t,card,F.unanswered(card));continue;}if(!ai.configured)continue;try{const a=await N.json('/api/check','POST',{caseId:id,answer:t.entries[id].answer});apply(t,card,a);}catch(error){toast(error.message);break;}}}finally{gradeBusy=false;if(['result','test'].includes(ui.push))render({keepScroll:true});N.haptic('success');}}
