 function startSync(){sync?.stop();if(!N.server||!N.paired){syncStatus={phase:'local'};updateBadges();return;}sync=window.LernpassSync.create({key:KEY,storage:store,getState:()=>state,normalize:s=>C.normalize(s,cards),applyState(value){state=value;const saved=saveWithoutSync();if(saved)render({keepScroll:true});return saved;},canApply:()=>!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!gradeBusy,fetcher:(...args)=>N.request(...args),schedule:(fn,ms)=>setTimeout(fn,ms===1200?1500:ms),onStatus(value){syncStatus=value;updateBadges();}});sync.start();}
