 const imageCache=new Map();async function loadImages(){for(const el of document.querySelectorAll('[data-private-image]')){const id=el.dataset.privateImage;try{let url=imageCache.get(id);if(!url){const r=await N.request('/api/worksheet-images/'+id);if(!r.ok)throw Error();url=URL.createObjectURL(await r.blob());imageCache.set(id,url);if(imageCache.size>36){const [first,old]=imageCache.entries().next().value;URL.revokeObjectURL(old);imageCache.delete(first);}}if(el.isConnected)el.src=url;}catch{el.alt='Bild momentan nicht erreichbar. Verbinde den Server.';}}}
