 async function exportWorkbook(){let html='<!doctype html><html lang="de"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mein MEC-H1-Fragenkatalog</title><style>body{font:16px system-ui;max-width:900px;margin:40px auto;padding:20px;line-height:1.6}article{break-inside:avoid;border-bottom:1px solid #bbb;padding:24px 0}img{max-width:100%;max-height:550px}pre{white-space:pre-wrap;font:inherit}small{color:#555}</style><h1>Mein Mechatronik-Fragenkatalog</h1><p>Eigene Lernhilfen · kein offizieller Lösungsschlüssel</p>';for(const card of cards){const e=Q.entry(state,card.id);html+=`<article><small>${card.id} · ${esc(card.category)}</small><h2>${esc(card.title)}</h2><p>${esc(card.question)}</p><h3>Meine Antwort</h3><pre>${esc(e.text)||'Noch offen.'}</pre>`;for(const image of e.images){const r=await N.request('/api/worksheet-images/'+image.id);if(!r.ok)throw Error('Nicht alle Bilder konnten geladen werden. Verbinde den Server und exportiere erneut.');const bytes=new Uint8Array(await r.arrayBuffer());let raw='';for(const b of bytes)raw+=String.fromCharCode(b);html+=`<figure><img alt="${esc(image.caption||image.name)}" src="data:${r.headers.get('content-type')};base64,${btoa(raw)}"><figcaption>${esc(image.caption)}</figcaption></figure>`;}html+='<details><summary>Musterantwort</summary>'+card.answer.map(p=>`<h3>${esc(p.label)}</h3><p>${esc(p.text)}</p>`).join('')+'</details></article>';}await N.saveFile('Lernpass-Katalog-'+C.today()+'.html',html,'text/html');toast('Katalog mit eigenen Antworten exportiert.');}
