 document.addEventListener('keydown',e=>{const inText=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if((e.ctrlKey||e.metaKey)&&/^[1-4]$/.test(e.key)){e.preventDefault();go(tabs[+e.key-1][0]);}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();go('catalog');$('catSearch').focus();}else if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&ui.push==='test'){e.preventDefault();open('submit');}else if(e.key==='Escape'){if(ui.sheet){ui.sheet=null;render({keepScroll:true});}else if(ui.push)go('learn');}else if(!inText&&ui.push==='unit'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const u=unit();u.position=Math.max(0,Math.min(u.ids.length-1,u.position+(e.key==='ArrowLeft'?-1:1)));save();render();}else if(['Enter',' '].includes(e.key)&&e.target.matches('[role=button]')){e.preventDefault();e.target.click();}else if(e.key==='Tab'&&ui.sheet){const list=[...document.querySelectorAll('.sheet button:not(:disabled),.sheet input,.sheet textarea,.sheet select,.sheet a[href]')].filter(el=>el.offsetParent!==null);if(list.length){const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}});
